"use client";

// Automation of one client: a report generated by itself, already shared, with the
// link ready to copy and send. Created and edited in three steps, like in Reportei:
// type, report data, details. One automation per client.

import { useCallback, useEffect, useState } from "react";
import Link from "next/link";
import { useTranslations } from "next-intl";
import { toast } from "sonner";
import { Check, Copy, FileText, Link2, MessageCircle, Pencil, Zap } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/dashboard/skeleton";
import { useHasPermission } from "@/hooks/use-permissions";
import { ANALYSIS_PERIODS, FREQUENCIES, isFrequency, type AnalysisPeriod, type ComparePeriod, type Frequency } from "@/lib/reportei/automation";
import { showDate, showDateTime } from "@/lib/reportei/format";
import { cn } from "@/lib/utils";
import { useTemplates } from "./use-templates";

interface Automation {
  id: string;
  frequency: Frequency;
  active: boolean;
  name: string | null;
  templateId: string | null;
  analysisPeriod: AnalysisPeriod | null;
  comparePeriod: ComparePeriod | null;
  reportTitle: string | null;
  lastRunOn: string | null;
  lastError: string | null;
  lastReport: { id: string; title: string; shareToken: string | null; createdAt: string } | null;
}

type State = { kind: "loading" } | { kind: "error" } | { kind: "ready"; automation: Automation | null };

const field = "h-9 w-full rounded-lg border border-input bg-transparent px-2.5 text-sm text-foreground outline-none focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 disabled:opacity-60 dark:bg-input/30";
const heading = "text-lg font-semibold text-foreground";

const STEPS = [
  { title: "Tipo de automação", hint: "O primeiro passo é escolher o tipo de automação." },
  { title: "Dados do relatório", hint: "Escolha o template e preencha os dados do relatório." },
  { title: "Detalhes da automação", hint: "E por fim, configure a frequência e o nome da automação." },
];

/** A choice card, selected or not (disabled ones show a small "Em breve"). */
function Choice({ selected, disabled, onClick, icon: Icon, title, hint, badge }: { selected?: boolean; disabled?: boolean; onClick?: () => void; icon: typeof Zap; title: string; hint?: string; badge?: string }) {
  return (
    <button
      type="button"
      role="radio"
      aria-checked={!!selected}
      disabled={disabled}
      onClick={onClick}
      className={cn(
        "flex w-full flex-col gap-1.5 rounded-xl border p-4 text-left transition-colors",
        selected ? "border-primary bg-primary/5 ring-1 ring-primary" : "border-border bg-card",
        disabled ? "cursor-not-allowed opacity-50" : !selected && "hover:border-primary/40 hover:bg-muted/50",
      )}
    >
      <span className="flex items-center gap-2 text-sm font-semibold text-foreground">
        <Icon className="h-4 w-4 shrink-0 text-primary" />
        {title}
        {badge && <span className="ml-auto rounded-full bg-muted px-2 py-0.5 text-[10px] font-medium text-muted-foreground">{badge}</span>}
      </span>
      {hint && <span className="text-xs text-muted-foreground">{hint}</span>}
    </button>
  );
}

export function AutomationPanel({ clientId, clientName, hasIntegrations }: { clientId: string; clientName?: string; hasIntegrations: boolean }) {
  const t = useTranslations("Operational.reportei.automationsPanel");
  const canEdit = useHasPermission("operational", "tasks", "edit_boards");
  const [state, setState] = useState<State>({ kind: "loading" });
  const [wizard, setWizard] = useState<number | null>(null); // null = summary; 1..3 = step
  const [frequency, setFrequency] = useState<Frequency>("weekly");
  const [saving, setSaving] = useState(false);
  const [copied, setCopied] = useState(false);
  const [templateId, setTemplateId] = useState<string | null>(null);
  const [analysisPeriod, setAnalysisPeriod] = useState<AnalysisPeriod | null>(null);
  const [comparePeriod, setComparePeriod] = useState<ComparePeriod | null>(null);
  const [reportTitle, setReportTitle] = useState("");
  const [name, setName] = useState("");
  const { templates } = useTemplates();

  const fill = useCallback((a: Automation | null) => {
    if (!a) return;
    if (isFrequency(a.frequency)) setFrequency(a.frequency);
    setTemplateId(a.templateId);
    setAnalysisPeriod(a.analysisPeriod);
    setComparePeriod(a.comparePeriod);
    setReportTitle(a.reportTitle ?? "");
    setName(a.name ?? "");
  }, []);

  const load = useCallback(async () => {
    const res = await fetch(`/api/operational/reportei/clients/${clientId}/automation`);
    if (!res.ok) return setState({ kind: "error" });
    const { automation } = (await res.json()) as { automation: Automation | null };
    fill(automation);
    setState({ kind: "ready", automation });
  }, [clientId, fill]);

  useEffect(() => {
    // Initial fetch; setState happens after the await, not synchronously.
    void load();
  }, [load]);

  /** Saves every setting; `over` changes some of them (the switch, for instance). */
  async function save(over: Partial<{ active: boolean }> = {}) {
    const next = {
      frequency,
      active: state.kind === "ready" ? (state.automation?.active ?? true) : true,
      templateId,
      analysisPeriod,
      comparePeriod,
      reportTitle: reportTitle.trim() || null,
      name: name.trim() || null,
      ...over,
    };
    setSaving(true);
    try {
      const res = await fetch(`/api/operational/reportei/clients/${clientId}/automation`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(next),
      });
      if (!res.ok) return toast.error(t("saveError"));
      const { automation } = (await res.json()) as { automation: Automation };
      fill(automation);
      setState({ kind: "ready", automation });
      setWizard(null);
      toast.success(t("saved"));
    } catch {
      toast.error(t("saveError"));
    } finally {
      setSaving(false);
    }
  }

  if (!hasIntegrations) return <p className="text-sm text-muted-foreground">{t("noIntegrations")}</p>;
  if (state.kind === "loading") return <Skeleton className="h-40" />;
  if (state.kind === "error") return <p className="text-sm text-red-500">{t("error")}</p>;

  const { automation } = state;
  const link = automation?.lastReport?.shareToken ? `${window.location.origin}/r/${automation.lastReport.shareToken}` : "";
  const templateName = automation?.templateId ? templates?.find((x) => x.id === automation.templateId)?.name : null;

  async function copy() {
    try {
      await navigator.clipboard.writeText(link);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      toast.error(t("copyError"));
    }
  }

  // --- The three steps -------------------------------------------------------
  if (wizard !== null) {
    const step = STEPS[wizard - 1];
    return (
      <div className="grid items-start gap-8 lg:grid-cols-[16rem_minmax(0,1fr)] lg:gap-14">
        <div className="space-y-3">
          <span className="flex h-12 w-12 items-center justify-center rounded-full border-4 border-primary/25 border-t-primary text-xs font-bold text-foreground">{wizard}/3</span>
          <h2 className="text-xl font-bold text-foreground">{step.title}</h2>
          <p className="text-sm text-muted-foreground">{step.hint}</p>
        </div>

        <div className="max-w-2xl space-y-6">
          {wizard === 1 && (
            <>
              <h3 className={heading}>Tipo de automação</h3>
              <div className="grid gap-3 sm:grid-cols-2" role="radiogroup" aria-label="Tipo de automação">
                <Choice selected icon={FileText} title="Automação de relatório" hint="Automatiza a criação do relatório e deixa o link pronto para enviar." />
                <Choice disabled icon={MessageCircle} title="Automações via WhatsApp" hint="Envio automático de resumos com as principais métricas." badge="Em breve" />
              </div>
              <p className="text-sm text-muted-foreground">O relatório usa todas as contas ligadas a {clientName ?? "este cliente"}.</p>
            </>
          )}

          {wizard === 2 && (
            <>
              <h3 className={heading}>Template</h3>
              <div className="grid gap-3 sm:grid-cols-2" role="radiogroup" aria-label={t("templateLabel")}>
                <Choice selected={templateId === null} icon={FileText} title={t("templateDefault")} hint="Modelo clássico, com as principais métricas." onClick={() => setTemplateId(null)} />
                {(templates ?? []).map((x) => (
                  <Choice key={x.id} selected={templateId === x.id} icon={FileText} title={x.name} hint={x.description || undefined} onClick={() => setTemplateId(x.id)} />
                ))}
              </div>

              <h3 className={heading}>Detalhes do relatório</h3>
              <label className="block space-y-1.5 text-sm">
                <span className="font-medium text-foreground">{t("titleLabel")}</span>
                <Input value={reportTitle} maxLength={200} placeholder={t("titlePlaceholder")} onChange={(e) => setReportTitle(e.target.value)} />
                <span className="block text-xs text-muted-foreground">Use {"{cliente}"} e {"{periodo}"} para preencher o nome e as datas.</span>
              </label>

              <div className="grid gap-4 sm:grid-cols-2">
                <label className="block space-y-1.5 text-sm">
                  <span className="font-medium text-foreground">{t("periodLabel")}</span>
                  <select value={analysisPeriod ?? ""} className={field} onChange={(e) => setAnalysisPeriod((e.target.value || null) as AnalysisPeriod | null)}>
                    <option value="">{t("periodAuto")}</option>
                    {ANALYSIS_PERIODS.map((p) => (
                      <option key={p} value={p}>
                        {t(`period_${p}`)}
                      </option>
                    ))}
                  </select>
                </label>
                <label className="block space-y-1.5 text-sm">
                  <span className="font-medium text-foreground">{t("compareLabel")}</span>
                  <select value={comparePeriod ?? ""} className={field} onChange={(e) => setComparePeriod((e.target.value || null) as ComparePeriod | null)}>
                    <option value="">{t("compareTemplate")}</option>
                    <option value="previous">{t("compareOn")}</option>
                    <option value="none">{t("compareOff")}</option>
                  </select>
                </label>
              </div>
            </>
          )}

          {wizard === 3 && (
            <>
              <h3 className={heading}>Método de envio</h3>
              <div className="grid gap-3 sm:grid-cols-3" role="radiogroup" aria-label="Método de envio">
                <Choice selected icon={Link2} title="Link público" hint="Gera o link para você copiar e enviar." />
                <Choice disabled icon={MessageCircle} title="WhatsApp" badge="Em breve" />
                <Choice disabled icon={FileText} title="E-mail" badge="Em breve" />
              </div>

              <h3 className={heading}>{t("frequencyLabel")}</h3>
              <div className="grid gap-3 sm:grid-cols-2" role="radiogroup" aria-label={t("frequencyLabel")}>
                {FREQUENCIES.map((f) => (
                  <Choice key={f} selected={frequency === f} icon={Zap} title={t(`freq_${f}`)} hint={t(`freqHint_${f}`)} onClick={() => setFrequency(f)} />
                ))}
              </div>

              <h3 className={heading}>Título da automação</h3>
              <Input value={name} maxLength={120} placeholder={`Ex.: Relatório mensal de ${clientName ?? "cliente"}`} onChange={(e) => setName(e.target.value)} aria-label="Título da automação" />
            </>
          )}

          <div className="flex items-center justify-between pt-2">
            <Button variant="outline" size="sm" disabled={saving} onClick={() => setWizard(wizard === 1 ? null : wizard - 1)}>
              {wizard === 1 ? "Cancelar" : "Voltar"}
            </Button>
            {wizard < 3 ? (
              <Button size="sm" onClick={() => setWizard(wizard + 1)}>
                Avançar
              </Button>
            ) : (
              <Button size="sm" disabled={saving} onClick={() => void save()}>
                {automation ? "Salvar automação" : "Finalizar e criar automação"}
              </Button>
            )}
          </div>
        </div>
      </div>
    );
  }

  // --- The automation, once it exists ----------------------------------------
  return (
    <div className="max-w-2xl space-y-5">
      <p className="text-sm text-muted-foreground">{t("intro")}</p>

      {!automation ? (
        canEdit && (
          <Button size="sm" onClick={() => setWizard(1)}>
            <Zap className="mr-1.5 h-4 w-4" />
            Criar automação
          </Button>
        )
      ) : (
        <section className="space-y-4 rounded-xl border border-border bg-card p-4">
          <div className="flex flex-wrap items-center gap-3">
            <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-orange-500/15 text-orange-600">
              <Zap className="h-4 w-4" />
            </span>
            <div className="min-w-0 flex-1">
              <p className="truncate text-sm font-semibold text-foreground">{automation.name ?? automation.reportTitle ?? `Relatório automático de ${clientName ?? "cliente"}`}</p>
              <p className="text-xs text-muted-foreground">
                {t(`freq_${automation.frequency}`)} · {templateName ?? t("templateDefault")}
              </p>
            </div>
            <span className={cn("rounded-full px-2 py-0.5 text-[11px] font-medium", automation.active ? "bg-emerald-500/15 text-emerald-500" : "bg-muted text-muted-foreground")}>
              {automation.active ? t("statusOn") : t("statusOff")}
            </span>
            {canEdit && (
              <div className="flex items-center gap-2">
                <Button variant="outline" size="sm" onClick={() => setWizard(1)}>
                  <Pencil className="mr-1.5 h-4 w-4" />
                  Editar
                </Button>
                <Button variant={automation.active ? "outline" : "default"} size="sm" disabled={saving} onClick={() => void save({ active: !automation.active })}>
                  {automation.active ? t("pause") : t("resume")}
                </Button>
              </div>
            )}
          </div>
        </section>
      )}

      {automation?.lastError && <p className="text-sm text-red-500">{t(`error_${automation.lastError}`)}</p>}

      {automation && (
        <section className="space-y-3 rounded-xl border border-border bg-card p-4">
          <h3 className="text-sm font-semibold text-foreground">{t("lastTitle")}</h3>
          {automation.lastReport ? (
            <>
              <Link href={`/operational/reportei/relatorios/${automation.lastReport.id}`} className="flex items-center gap-2 text-sm text-foreground hover:underline">
                <FileText className="h-4 w-4 shrink-0 text-primary" />
                <span className="truncate">{automation.lastReport.title}</span>
                <span className="shrink-0 text-xs text-muted-foreground">{showDateTime(automation.lastReport.createdAt)}</span>
              </Link>
              {link && (
                <div className="flex flex-wrap items-center gap-2">
                  <Input readOnly value={link} onFocus={(e) => e.currentTarget.select()} className="h-8 w-80 max-w-full text-xs" aria-label={t("linkLabel")} />
                  <Button variant="outline" size="sm" onClick={copy}>
                    {copied ? <Check className="mr-1.5 h-4 w-4" /> : <Copy className="mr-1.5 h-4 w-4" />}
                    {copied ? t("copied") : t("copy")}
                  </Button>
                </div>
              )}
              {!link && <p className="text-xs text-muted-foreground">{t("linkOff")}</p>}
            </>
          ) : (
            <p className="text-sm text-muted-foreground">{automation.lastRunOn ? t("lastRunNoReport", { date: showDate(automation.lastRunOn) }) : t("neverRan")}</p>
          )}
        </section>
      )}
    </div>
  );
}
